<?php
namespace backend\models;
use yii\base\Model; use yii\data\ActiveDataProvider;
class AcademicCalendarSearch extends AcademicCalendar { public function rules() { return [[['academic_activity_id'], 'integer'], [['period', 'start_date', 'end_date', 'description'], 'safe'], [['is_academic_holiday', 'is_national_holiday'], 'boolean']]; } public function scenarios() { return Model::scenarios(); } public function search($params) { $query = AcademicCalendar::find()->joinWith('academicActivity'); $provider = new ActiveDataProvider(['query' => $query, 'pagination' => ['pageSize' => 20], 'sort' => ['defaultOrder' => ['start_date' => SORT_ASC]]]); $this->load($params); if (!$this->validate()) return $provider; $query->andFilterWhere(['academic_calendars.academic_activity_id' => $this->academic_activity_id, 'academic_calendars.period' => $this->period, 'academic_calendars.is_academic_holiday' => $this->is_academic_holiday, 'academic_calendars.is_national_holiday' => $this->is_national_holiday])->andFilterWhere(['like', 'academic_calendars.description', $this->description]); return $provider; } }
